public class ParquetFileReaderReadBloomFilterTests {

  @Test
  public void returnsNullForAbsentBloomFilterWithoutSeeking() throws Exception {
    TrackingSeekableInputStream stream = new TrackingSeekableInputStream(new byte[16]);
    ParquetFileReader reader = newReader(stream);
    ColumnChunkMetaData metadata = metadataWithBloomFilter(-1L, -1);

    BloomFilter result = reader.readBloomFilter(metadata);

    assertNull(result);
    assertEquals(0L, stream.getPos());
    reader.close();
  }

  @Test
  public void readsSupportedBloomFilterAndPreservesBitsetSize() throws Exception {
    byte[] bitset = new byte[32];
    bitset[0] = 1;

    BlockSplitBloomFilter source = new BlockSplitBloomFilter(bitset);
    source.insertHash(source.hash(0L));

    ByteArrayOutputStream encoded = new ByteArrayOutputStream();
    source.writeTo(encoded);

    TrackingSeekableInputStream stream =
        new TrackingSeekableInputStream(encoded.toByteArray());
    ParquetFileReader reader = newReader(stream);
    ColumnChunkMetaData metadata = metadataWithBloomFilter(0L, -1);

    BloomFilter result = reader.readBloomFilter(metadata);

    assertNotNull(result);
    assertEquals(bitset.length, result.getBitsetSize());
    assertTrue(
        result.findHash(result.hash(0L)),
        "The serialized bloom filter should contain the inserted hash");
    assertTrue(stream.getPos() > 0L);
    reader.close();
  }

