  private static final class TrackingSeekableInputStream extends SeekableInputStream {
    private final ByteArrayInputStream delegate;
    private long position;

    private TrackingSeekableInputStream(byte[] data) {
      this.delegate = new ByteArrayInputStream(data);
      this.position = 0L;
    }

    @Override
    public void seek(long newPos) throws IOException {
      if (newPos < 0 || newPos > Integer.MAX_VALUE) {
        throw new IOException("Invalid position: " + newPos);
      }
      delegate.reset();
      long skipped = delegate.skip(newPos);
      if (skipped != newPos) {
        throw new IOException("Unable to seek to position: " + newPos);
      }
      position = newPos;
    }

    @Override
    public long getPos() {
      return position;
    }

    @Override
    public int read() {
      int value = delegate.read();
      if (value >= 0) {
        position++;
      }
      return value;
    }

    @Override
    public int read(byte[] buffer, int offset, int length) {
      int count = delegate.read(buffer, offset, length);
      if (count > 0) {
        position += count;
      }
      return count;
    }

    @Override
    public int read(ByteBuffer buffer) {
      if (!buffer.hasRemaining()) {
        return 0;
      }

      byte[] temporary = new byte[Math.min(buffer.remaining(), 8192)];
      int count = read(temporary, 0, temporary.length);
      if (count > 0) {
        buffer.put(temporary, 0, count);
      }
      return count;
    }

    @Override
    public void readFully(byte[] buffer) throws IOException {
      readFully(buffer, 0, buffer.length);
    }

    @Override
    public void readFully(byte[] buffer, int offset, int length) throws IOException {
      int remaining = length;
      int currentOffset = offset;
      while (remaining > 0) {
        int count = read(buffer, currentOffset, remaining);
        if (count < 0) {
          throw new IOException("Unexpected end of stream");
        }
        if (count == 0) {
          continue;
        }
        currentOffset += count;
        remaining -= count;
      }
    }

    @Override
    public void readFully(ByteBuffer buffer) throws IOException {
      while (buffer.hasRemaining()) {
        int count =
            read(buffer.array(), buffer.arrayOffset() + buffer.position(), buffer.remaining());
        if (count < 0) {
          throw new IOException("Unexpected end of stream");
        }
        buffer.position(buffer.position() + count);
      }
    }

    @Override
    public void close() throws IOException {
      delegate.close();
    }
